const input=$json.body??$json;
const text=v=>v===null||v===undefined?'':String(v).trim();
const bool=v=>typeof v==='boolean'?v:['true','1','yes','on'].includes(text(v).toLowerCase());

const stuck_processing_minutes=Number(input.stuck_processing_minutes??15);
const retry_batch_size=Number(input.retry_batch_size??100);
const confirm_maintenance=bool(input.confirm_maintenance);
const errors=[];

if(!Number.isInteger(stuck_processing_minutes)||stuck_processing_minutes<5||stuck_processing_minutes>1440){
  errors.push({field:'stuck_processing_minutes',message:'زمان Stuck باید بین 5 و 1440 دقیقه باشد.'});
}
if(!Number.isInteger(retry_batch_size)||retry_batch_size<1||retry_batch_size>1000){
  errors.push({field:'retry_batch_size',message:'اندازه Batch باید بین 1 و 1000 باشد.'});
}
if(confirm_maintenance!==true){
  errors.push({field:'confirm_maintenance',message:'اجرای نگهداری باید تأیید شود.'});
}

return [{json:{
  stuck_processing_minutes,retry_batch_size,confirm_maintenance,
  validation_status:errors.length?'invalid':'valid',errors
}}];
